function refillPhaseRandomBag(group){const f=state.patternFlow[group],indices=phasePatternIndices(group);if(!f||!indices.length)return[];const bag=shuffle(indices.slice());if(bag.length>1&&bag[0]===state.idx){const swapAt=bag.findIndex((v,i)=>i>0&&v!==state.idx);if(swapAt>0)[bag[0],bag[swapAt]]=[bag[swapAt],bag[0]]}f.randomBag=bag;return bag}
function nextPatternInCurrentPhase(){const group=cur().g,f=state.patternFlow[group],indices=phasePatternIndices(group),pos=indices.indexOf(state.idx);if(!f||!indices.length)return state.idx;if(!f.orderedComplete){if(pos>=0&&pos<indices.length-1)return indices[pos+1];f.orderedComplete=true;f.randomBag=[]}if(!f.randomBag.length)refillPhaseRandomBag(group);const next=f.randomBag.shift();f.lastIndex=next;return next}
function buildUI(){}
function updateUI(){}
function playCinematic(type,nextIndex,nextOpts={}){const originX=state.boss.x,originY=state.boss.y;state.cinematic={active:true,type,t:0,nextIndex:(nextIndex+PATTERNS.length)%PATTERNS.length,nextOpts:{...nextOpts},originX,originY};state.intro={active:false,t:0};state.patternDone=false;state.patternDoneT=0;state.elapsed=0;state.shots=[];state.bullets=[];state.stars=[];state.particles=[];state.waves=[];state.labels=[];state.hitFlash=0;state.history=[];state.lastHistory=0;state.fireCd=0;state.shake=0;state.shakeTime=0;state.player.x=400;state.player.y=820;state.player.inv=0;state.player.lives=3;state.boss.flash=0;state.boss.motionTilt=0;state.boss.motionScale=1;state.boss.vx=0;state.boss.vy=0;if(type==="phase1Clear"){state.boss.x=originX;state.boss.y=originY}else if(type==="phase2Transition"){state.boss.x=400;state.boss.y=440}else{state.boss.x=400;state.boss.y=160}state.bossHp=0;state.bossMax=2000;if(meetingPhasePack)meetingPhasePack.stop();updateUI()}
function applyPatternStart(i=state.idx,opts={}){const preserveField=!!opts.preserveField,fromCinematic=!!opts.fromCinematic,cinematicType=opts.cinematicType||"",oldGroup=cur()?.g,nextIndex=(i+PATTERNS.length)%PATTERNS.length,nextGroup=PATTERNS[nextIndex].g,phaseChanged=oldGroup!==nextGroup;if(meetingPhasePack)meetingPhasePack.stop();state.idx=nextIndex;state.elapsed=0;state.shots=[];state.victoryComplete=false;state.clearSeq.active=false;if(!preserveField){state.bullets=[];state.stars=[];state.particles=[];state.waves=[];state.labels=[];state.hitFlash=0;state.player.x=400;state.player.y=820;state.player.inv=1;state.player.lives=3;state.fireCd=0;state.shake=0}else{state.hitFlash=Math.max(0,state.hitFlash);state.player.inv=Math.max(state.player.inv,.18)}state.history=[];state.lastHistory=0;state.patternDone=false;state.patternDoneT=0;state.cleanup=null;state.q=initPattern(cur().kind);state.bossMax=nextGroup==="team"?2200:2000;if(fromCinematic||phaseChanged||opts.resetPhaseHp){state.bossHp=state.bossMax;if(phaseChanged||fromCinematic)resetPhasePatternFlow(nextGroup)}else state.bossHp=clamp(state.bossHp,0,state.bossMax);state.boss.r=nextGroup==="team"?86:82;if(fromCinematic){state.boss.x=400;state.boss.y=cinematicType==="phase2Transition"?160:205;state.boss.vx=0;state.boss.vy=0;state.boss.motionTilt=0;state.boss.motionScale=1;state.bossHandoff=cinematicType==="phase2Transition"?0:1.25}else state.bossHandoff=0;if(isMeetingPattern())startMeetingPattern(state.q);state.cinematic.active=false;updateUI()}
function startPattern(i=state.idx,opts={}){const nextIndex=(i+PATTERNS.length)%PATTERNS.length,target=PATTERNS[nextIndex],prev=PATTERNS[state.idx],isReplay=!!opts.replayCinematic,fromCinematic=!!opts.fromCinematic,skipCinematic=!!opts.skipCinematic;if(!fromCinematic&&!skipCinematic){if((isReplay&&target.g!=="team")||(!state.hasPlayedPhase1Intro&&target.g==="exam"&&nextIndex===0)){state.hasPlayedPhase1Intro=true;playCinematic("phase1Intro",nextIndex,opts);return}if((isReplay&&target.g==="team")||(state.hasPlayedPhase1Intro&&!state.hasPlayedPhase2Intro&&prev&&prev.g!==target.g&&target.g==="team")){state.hasPlayedPhase2Intro=true;playCinematic("phase2Transition",nextIndex,opts);return}}applyPatternStart(nextIndex,opts)}
function markFieldForNaturalExit(){for(const b of state.bullets){if(b.exiting)continue;b.exiting=true;b.exitAge=0;b.exitAlpha=1;const speed=Math.hypot(b.vx||0,b.vy||0);if(speed<125){const dl=b.x,dr=W-b.x,dt=b.y,db=H-b.y,m=Math.min(dl,dr,dt,db);let tx=b.x,ty=b.y;if(m===dl)tx=-120;else if(m===dr)tx=W+120;else if(m===dt)ty=-120;else ty=H+120;const a=Math.atan2(ty-b.y,tx-b.x);b.vx=Math.cos(a)*240;b.vy=Math.sin(a)*240}}for(const s of state.stars){s.exiting=true;s.exitAge=0;s.exitAlpha=1;if(Math.hypot(s.vx||0,s.vy||0)<80){s.vx=(s.x<W/2?-1:1)*rand(90,150);s.vy=-rand(180,260)}}}
function beginPatternCleanup(q,k){q.cleanup=true;q.cleanupT=0;q.cleanupAlpha=1;state.cleanup={kind:k,t:0,max:1.35};state.player.inv=Math.max(state.player.inv,1.2);markFieldForNaturalExit();if(k==="math"){q.problem=null;q.answers=[];q.next=999}else if(k==="circle"){q.next=999;q.chainLeft=0;q.chainDelay=999}else if(k==="grading"){q.next=999}else if(k==="secret"){q.next=999}else if(k==="books"){q.phase="cleanup";q.cleanupFloorStart=q.floor;q.cleanupRelease=false;for(const b of q.books){b.cleanupVy=0;b.cleanupVx=rand(-20,20)}}else if(k==="laserWave"){q.next=999;q.endQueued=true;q.canEnd=true;if(q.beam)q.beam.life=Math.min(q.beam.life,.26)}else if(k==="pptText"){q.batchTarget=0;q.next=999;for(const a of q.active||[]){const ang=Math.atan2(state.player.y-a.y,state.player.x-a.x);q.flying.push({text:a.text,x:a.x,y:a.y,w:Math.max(70,a.text.length*22),h:46,vx:Math.cos(ang)*rand(190,255),vy:Math.sin(ang)*rand(190,255),hp:35,dead:false,rot:0,cleanupSpawned:true})}q.active=[]}else if(k==="pptShape"){q.textBatch=0;q.next=999;q.textNext=999;q.drawJobs=[];q.obstacleExitT=0;q.obstacleExitPhase="chase";q.obstacles.forEach((o,i)=>{o.maxHp=o.maxHp||64;o.hp=o.hp??o.maxHp;o.dead=false;o.hitFlash=0;o.exitVx=0;o.exitVy=0;o.exitDelay=i*.12;o.exitSpeed=88+i*10;o.exitLocked=false;o.exitRot=rand(-.7,.7)})}else if(k==="format"){q.next=999}else if(k==="docs"){q.nextRefill=999;q.nextDroneFire=999}else if(k==="source"){q.next=999;q.stack=[];for(const c of q.cards){c.cleanupVy=c.landed?0:(c.vy||0);c.cleanupRot=rand(-1.2,1.2)}}else if(k==="chat"){q.closing=true;q.next=999;q.noticeQueue=0;q.noticeRequested=false}else if(k==="zoom"){q.next=999}else if(k==="shortcut"){q.next=999}}
function finishCurrentPattern(){if(state.patternDone)return;state.patternDone=true;state.patternDoneT=0;const q=state.q||{},k=cur().kind;if(k==="fbomb"&&q.phase!=="closing"&&q.phase!=="done"){q.phase="closing";q.phaseT=0;q.finishDelay=.12}beginPatternCleanup(q,k)}
function updatePatternCleanup(dt){const q=state.q||{},k=cur().kind;if(!state.cleanup)return true;state.cleanup.t+=dt;q.cleanupT=(q.cleanupT||0)+dt;q.cleanupAlpha=clamp(1-q.cleanupT/.85,0,1);
 if(k==="fbomb"){updateFBomb(q,dt);return q.phase==="done"||q.cleanupDone===true}
 if(k==="books"){const target=H+150,t=clamp(q.cleanupT/1.25,0,1),ease=t*t*(3-2*t);q.floor=lerp(q.cleanupFloorStart??q.floor,target,ease);if(q.cleanupT>.12&&!q.cleanupRelease){q.cleanupRelease=true;for(const b of q.books){b.state="cleanupFall";b.landed=false;b.cleanupVy=rand(30,90);b.cleanupVx=rand(-28,28)}}for(const b of q.books){if(b.state!=="cleanupFall")continue;b.cleanupVy+=880*dt;b.x+=b.cleanupVx*dt;b.y+=b.cleanupVy*dt;b.rot+=(b.cleanupVx>=0?1:-1)*dt*.38}q.cleanupAlpha=1;return q.cleanupT>1.25&&q.books.every(b=>b.y-b.h/2>H+35)}
 if(k==="source"){for(const c of q.cards){c.cleanupVy=(c.cleanupVy||0)+760*dt;c.y+=c.cleanupVy*dt;c.x+=(c.cleanupRot||0)*24*dt;c.rot=(c.rot||0)+(c.cleanupRot||0)*dt}return q.cleanupT>1.0&&q.cards.every(c=>c.y-c.h/2>H+20)}
 if(k==="grading"){for(const sh of q.sheets){sh.y+=(sh.vy||100)*dt;sh.vy=(sh.vy||100)+260*dt}return q.cleanupT>.9}
 if(k==="secret"){for(const b of q.bombs){b.vy=(b.vy||0)+520*dt;b.x+=(b.vx||0)*dt;b.y+=b.vy*dt;b.rot=(b.rot||0)+dt*2}return q.cleanupT>.9}
 if(k==="pptText"){for(const f of q.flying){if(f.dead)continue;f.x+=f.vx*dt;f.y+=f.vy*dt;f.rot+=dt*.9;if(Math.abs(state.player.x-f.x)<f.w/2&&Math.abs(state.player.y-f.y)<f.h/2)hitPlayer()}q.flying=q.flying.filter(f=>!f.dead&&f.x>-220&&f.x<W+220&&f.y>-160&&f.y<H+160);q.cleanupAlpha=1;return q.cleanupT>1.05&&q.flying.length===0}
 if(k==="pptShape"){q.obstacleExitT=(q.obstacleExitT||0)+dt;for(const f of q.falling){f.vy=(f.vy||0)+620*dt;f.x+=(f.vx||0)*dt;f.y+=f.vy*dt}q.falling=q.falling.filter(f=>f.y-f.r<H+80);for(const f of q.textFlying){f.x+=f.vx*dt;f.y+=f.vy*dt;f.rot+=dt*.9}q.textFlying=q.textFlying.filter(f=>f.x>-220&&f.x<W+220&&f.y>-160&&f.y<H+160);const chaseEnd=1.65;for(const o of q.obstacles){o.hitFlash=Math.max(0,(o.hitFlash||0)-dt);if(o.dead)continue;o.exitDelay=Math.max(0,(o.exitDelay||0)-dt);if(o.exitDelay>0)continue;if(q.obstacleExitT<chaseEnd){const dx=state.player.x-o.x,dy=state.player.y-o.y,d=Math.hypot(dx,dy)||1;const targetSp=o.exitSpeed||95,tx=dx/d*targetSp,ty=dy/d*targetSp;o.exitVx=lerp(o.exitVx||0,tx,dt*1.8);o.exitVy=lerp(o.exitVy||0,ty,dt*1.8);o.x+=o.exitVx*dt;o.y+=o.exitVy*dt;if(dist(o.x,o.y,state.player.x,state.player.y)<o.r+state.player.r)hitPlayer()}else{if(!o.exitLocked){const dx=state.player.x-o.x,dy=state.player.y-o.y,d=Math.hypot(dx,dy)||1;const coastSp=245+(o.exitSpeed||95)*.35;o.exitVx=dx/d*coastSp;o.exitVy=dy/d*coastSp;o.exitLocked=true}o.x+=o.exitVx*dt;o.y+=o.exitVy*dt}o.exitRot=(o.exitRot||0)+dt*.7}q.obstacles=q.obstacles.filter(o=>!o.dead&&o.x>-o.r-90&&o.x<W+o.r+90&&o.y>-o.r-90&&o.y<H+o.r+90);q.cleanupAlpha=1;return q.obstacleExitT>chaseEnd&&q.obstacles.length===0&&q.falling.length===0&&q.textFlying.length===0}
 if(k==="format"){for(const pg of q.pages){pg.x+=pg.vx*dt;pg.y+=pg.vy*dt;pg.rot+=dt*.08}return q.cleanupT>.85}
 if(k==="docs"){for(const r of q.refills){r.x+=r.vx*dt;r.y+=r.vy*dt}return q.cleanupT>.55}
 if(k==="circle"){for(const c of q.circles)c.life=(c.life||0)+dt;return q.cleanupT>.55}
 if(k==="chat")return q.cleanupT>.18
 if(k==="zoom")return q.cleanupT>.12
 if(isMeetingPattern(k))return q.cleanupT>.16
 return q.cleanupT>.55}
