 if(k==="secret"){for(const b of q.bombs){if(!b.dead&&dist(s.x,s.y,b.x,b.y)<b.r+s.r){b.hp-=s.damage;if(b.hp<=0){b.dead=true;burst(b.x,b.y,"#eee4ca",14);damageBoss(10,b.x,b.y)}return true}}}
 if(k==="books"){return false}
