 if(k==="pptShape"){for(const f of q.falling){if(!f.dead&&dist(s.x,s.y,f.x,f.y)<f.r+s.r){f.hp-=s.damage;if(f.hp<=0){f.dead=true;burst(f.x,f.y,"#ffab5e",16);damageBoss(6,f.x,f.y)}return true}}if(state.patternDone){for(const o of q.obstacles){if(o.dead)continue;if(dist(s.x,s.y,o.x,o.y)<o.r+s.r){o.maxHp=o.maxHp||64;o.hp=(o.hp??o.maxHp)-s.damage;o.hitFlash=.13;burst(s.x,s.y,"#a9d6ff",4);if(o.hp<=0){o.dead=true;burst(o.x,o.y,"#6fb7ff",22);spawnWave(o.x,o.y,"#8fd7ff",8,.48,250);triggerScreenShake(6,.16)}return true}}}}
 if(k==="format"){for(const p of q.pages){if(!p.dead&&Math.abs(s.x-p.x)<p.w/2&&Math.abs(s.y-p.y)<p.h/2){p.hp-=s.damage;if(p.hp<=0){p.dead=true;burst(p.x,p.y,p.color,14);damageBoss(6,p.x,p.y)}return true}}}
 if(k==="source"){for(const c of q.cards){if(!c.dead&&Math.abs(s.x-c.x)<c.w/2&&Math.abs(s.y-c.y)<c.h/2){c.hp-=s.damage;if(c.hp<=0){c.dead=true;burst(c.x,c.y,c.unknown?"#ff607a":"#72dfff",12);if(c.unknown)damageBoss(9,c.x,c.y)}return true}}}
 if(k==="blackhole"){const h=q.hole;if(h&&dist(s.x,s.y,h.x,h.y)<h.r*.7+s.r){burst(s.x,s.y,"#7f7dff",4);return true}}
