 if(k==="math")updateMath(q,dt);else if(k==="fbomb")updateFBomb(q,dt);else if(k==="circle")updateCircle(q,dt);else if(k==="corruptBarrage")updateCorruptBarrage(q,dt);else if(k==="grading")updateGrading(q,dt);else if(k==="secret")updateSecret(q,dt);else if(k==="books")updateBooks(q,dt);else if(k==="blackhole")updateBlackhole(q,dt);else if(k==="laserWave")updateLaserWave(q,dt);else if(k==="pptText")updatePptText(q,dt);else if(k==="pptShape")updatePptShape(q,dt);else if(k==="format")updateFormat(q,dt);else if(k==="docs")updateDocs(q,dt);else if(k==="source")updateSource(q,dt);else if(k==="chat")updateChat(q,dt);else if(k==="zoom")updateZoom(q,dt);else if(isMeetingPattern(k))updateMeetingPattern(q,dt);else if(k==="shortcut")updateShortcut(q,dt);
