function newMathProblem(){const ops=["+","−","×","÷"],op=ops[randi(0,3)];let a,b,ans;if(op==="+"){a=randi(3,29);b=randi(2,24);ans=a+b}else if(op==="−"){a=randi(12,35);b=randi(2,a-1);ans=a-b}else if(op==="×"){a=randi(2,9);b=randi(2,9);ans=a*b}else{b=randi(2,9);ans=randi(2,9);a=b*ans}const wrong=new Set([ans]);while(wrong.size<4)wrong.add(Math.max(0,ans+randi(-8,8)));const arr=shuffle([...wrong]);return{a,b,op,ans,text:`${a} ${op} ${b} = ?`,choices:arr}}
