 for(let i=0;i<size;i++){const base={...scenarioMessages[(q.index+i)%scenarioMessages.length]};const isLong=base.text.length>=18||Math.random()<.22;base.long=isLong;base.massive=base.text.length>=24||(isLong&&Math.random()<.28);base.vertical=isLong||Math.random()<.28;if(base.massive)base.vertical=true;batch.push({...base,typed:"",i:0,t:0,pause:0,entered:false,flash:0,batch:q.batchNo})}
