function drawCircle(q){for(const c of q.circles){if(c.exploded){const a=1-c.life/.65;ctx.globalAlpha=Math.max(0,a);const g=ctx.createRadialGradient(c.x,c.y,10,c.x,c.y,c.r*1.25);g.addColorStop(0,"rgba(255,245,160,.95)");g.addColorStop(.35,"rgba(255,67,74,.8)");g.addColorStop(1,"rgba(255,31,58,0)");ctx.fillStyle=g;ctx.beginPath();ctx.arc(c.x,c.y,c.r*1.25,0,TAU);ctx.fill();ctx.globalAlpha=1;continue}ctx.strokeStyle="#e33145";ctx.lineWidth=9;ctx.lineCap="round";ctx.beginPath();const seg=80,end=Math.floor(seg*c.p);for(let i=0;i<=end;i++){const a=-Math.PI/2+i/seg*TAU,j=Math.sin(i*12.37+c.seed)*3.4,r=c.r+j,x=c.x+Math.cos(a)*r,y=c.y+Math.sin(a)*r;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();ctx.fillStyle="rgba(255,53,74,.1)";ctx.beginPath();ctx.arc(c.x,c.y,c.r,0,TAU);ctx.fill()} }
