function drawBooks(q){ctx.fillStyle="#7d5936";ctx.fillRect(0,q.floor,W,H-q.floor);ctx.fillStyle="#4f3a22";ctx.fillRect(0,q.floor-8,W,8);for(const b of q.books){let sx=0,sy=0;if(b.state==="warning"){const amp=6+2.6*Math.sin(state.t*24+b.floatPhase);sx=Math.sin(state.t*48+b.floatPhase)*amp;sy=Math.cos(state.t*41+b.floatPhase)*amp*.48}ctx.save();ctx.translate(b.x+sx,b.y+sy);ctx.rotate(b.rot||0);const warning=b.state==="warning",tone=warning?"#ffd15a":b.state==="embedded"?"#d6a85a":"#ffcf7a";if(warning){const pulse=.5+.5*Math.sin(state.t*13+b.floatPhase);ctx.shadowColor="#ff536f";ctx.shadowBlur=18+12*pulse;ctx.strokeStyle=`rgba(255,74,101,${.62+.3*pulse})`;ctx.lineWidth=5;ctx.beginPath();ctx.roundRect(-b.w/2-7,-b.h/2-7,b.w+14,b.h+14,11);ctx.stroke()}ctx.fillStyle=tone;ctx.strokeStyle="#5e4426";ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(-b.w/2,-b.h/2,b.w,b.h,7);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle="#3b2a1b";ctx.fillRect(-b.w/2+12,-b.h/2+10,b.w-24,12);const nameSize=clamp(Math.floor(b.w/8.6),12,18);ctx.fillStyle="#2e2116";ctx.font=`900 ${nameSize}px Arial`;ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillText(b.name,0,Math.min(8,b.h*.1));ctx.textAlign="left";ctx.textBaseline="alphabetic";ctx.restore()}if(q.preview){const pf=bookLandingFloor(q,q.preview);ctx.fillStyle="rgba(255,213,90,.17)";ctx.strokeStyle="#ffd45a";ctx.lineWidth=5;ctx.setLineDash([12,8]);ctx.strokeRect(q.preview.x-q.preview.w/2,pf-q.preview.h,q.preview.w,q.preview.h);ctx.setLineDash([])}}

function drawLaserWaveBeam(beam){const len=Math.hypot(beam.x2-beam.originX,beam.y2-beam.originY),w=beam.width*(1+.06*Math.sin(state.t*20+beam.pulse)),step=16,amp=Math.max(2.8,w*.18);ctx.save();ctx.translate(beam.originX,beam.originY);ctx.rotate(beam.angle);ctx.beginPath();for(let x=0;x<=len+18;x+=step){const y=-w/2+Math.sin(x*.055+state.t*16)*amp;if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}for(let x=len+18;x>=0;x-=step){const y=w/2+Math.sin(x*.055+state.t*16+.9)*amp;ctx.lineTo(x,y)}ctx.closePath();const g=ctx.createLinearGradient(0,-w/2,0,w/2);g.addColorStop(0,"rgba(255,88,150,.78)");g.addColorStop(.24,"rgba(255,162,220,.95)");g.addColorStop(.5,"rgba(255,255,255,.98)");g.addColorStop(.76,"rgba(140,228,255,.94)");g.addColorStop(1,"rgba(82,198,255,.76)");ctx.fillStyle=g;ctx.shadowColor="rgba(255,128,196,.72)";ctx.shadowBlur=26;ctx.fill();ctx.globalAlpha=.46;const core=ctx.createLinearGradient(0,-w*.14,0,w*.14);core.addColorStop(0,"rgba(255,255,255,0)");core.addColorStop(.5,"rgba(255,255,255,.96)");core.addColorStop(1,"rgba(255,255,255,0)");ctx.fillStyle=core;ctx.fillRect(0,-w*.16,len,w*.32);ctx.restore();ctx.save();const flare=ctx.createRadialGradient(beam.originX,beam.originY,0,beam.originX,beam.originY,44);flare.addColorStop(0,"#ffffff");flare.addColorStop(.22,"rgba(255,138,209,.95)");flare.addColorStop(1,"rgba(255,255,255,0)");ctx.fillStyle=flare;ctx.beginPath();ctx.arc(beam.originX,beam.originY,44,0,TAU);ctx.fill();ctx.restore()}
function drawLaserWave(q){const originX=state.boss.x,originY=state.boss.y+36,angle=q.phase==="track"?q.trackAngle:q.lockedAngle,end=rayPoint(originX,originY,angle);if(q.phase==="track"||q.phase==="blink"){const blink=q.phase==="blink"?((Math.floor(q.phaseT/.18)%2)===0?1:.24):1;ctx.save();ctx.globalAlpha=.28+.5*blink;ctx.strokeStyle=q.phase==="blink"?"#ff78b3":"#79d6ff";ctx.lineWidth=q.phase==="blink"?4.2:3.2;ctx.setLineDash([12,8]);ctx.lineDashOffset=-state.t*180;ctx.shadowColor=q.phase==="blink"?"rgba(255,120,179,.6)":"rgba(121,214,255,.42)";ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(originX,originY);ctx.lineTo(end.x,end.y);ctx.stroke();ctx.setLineDash([]);for(let i=0;i<3;i++){ctx.globalAlpha=.26+.18*blink;ctx.strokeStyle=i===2?"rgba(255,255,255,.9)":"rgba(255,168,218,.72)";ctx.lineWidth=2.2;ctx.beginPath();ctx.arc(originX,originY,15+i*11+Math.sin(state.t*7+i)*2,0,TAU);ctx.stroke()}ctx.restore()}if(q.beam)drawLaserWaveBeam(q.beam)}
