function drawPptShape(q){const windowVisible=q.windowT>=.08;if(windowVisible)drawPptChrome(q.slide);for(const o of q.obstacles){if(o.dead)continue;ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.exitRot||0);ctx.fillStyle=(o.hitFlash||0)>0?"#ffffff":"#4f8fdb";ctx.strokeStyle=(o.hitFlash||0)>0?"#8fd7ff":"#173155";ctx.lineWidth=6;ctx.shadowColor=state.patternDone?"rgba(79,143,219,.5)":"transparent";ctx.shadowBlur=state.patternDone?12:0;ctx.beginPath();ctx.arc(0,0,o.r,0,TAU);ctx.fill();ctx.stroke();if(state.patternDone){ctx.strokeStyle="rgba(255,255,255,.58)";ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,o.r*.58,0,TAU);ctx.stroke()}ctx.restore()}if(!windowVisible){ctx.textAlign="left";return}for(const d of q.drawJobs){const x=lerp(d.x1,d.x2,clamp(d.p,0,1)),y=lerp(d.y1,d.y2,clamp(d.p,0,1));ctx.strokeStyle=d.obstacle?"#4f8fdb":"#f39a52";ctx.lineWidth=6;ctx.setLineDash([9,6]);ctx.strokeRect(d.x1,d.y1,x-d.x1,y-d.y1);ctx.setLineDash([]);drawCursor(d.cursor)}for(const a of q.textActive){ctx.fillStyle="#20222b";ctx.font="900 24px Arial";ctx.fillText(a.typed,a.x,a.y);ctx.strokeStyle="#d3354f";ctx.lineWidth=2;ctx.strokeRect(a.x-8,a.y-30,Math.max(35,a.typed.length*26),38);drawCursor(a.cursor)}for(const t of q.textFlying){ctx.save();ctx.translate(t.x,t.y);ctx.rotate(t.rot);ctx.fillStyle="#f5f1e8";ctx.strokeStyle="#d5465c";ctx.lineWidth=4;ctx.beginPath();ctx.roundRect(-t.w/2,-t.h/2,t.w,t.h,9);ctx.fill();ctx.stroke();ctx.fillStyle="#252733";ctx.font="900 18px Arial";ctx.textAlign="center";ctx.fillText(t.text,0,6);ctx.restore()}for(const f of q.falling){ctx.fillStyle="#f39a52";ctx.strokeStyle="#5d2d13";ctx.lineWidth=6;if(f.shape==="circle"){ctx.beginPath();ctx.arc(f.x,f.y,f.r,0,TAU);ctx.fill();ctx.stroke()}else{ctx.beginPath();ctx.roundRect(f.x-f.r,f.y-f.r,f.r*2,f.r*2,9);ctx.fill();ctx.stroke()}}ctx.textAlign="left"}
