function wrapText(text,x,y,maxW,lineH){let line="",yy=y;for(const ch of text){const test=line+ch;if(ctx.measureText(test).width>maxW&&line){ctx.fillText(line,x,yy);line=ch;yy+=lineH}else line=test}ctx.fillText(line,x,yy)}

let completeNotified=false;
function syncExternalPlayerIn(){const p=adapter.getPlayer();if(!p)return;state.player.x=p.x;state.player.y=p.y;state.player.r=p.radius;if(p.invulnerable)state.player.inv=Math.max(state.player.inv,.08)}
function syncExternalPlayerOut(){if(state.cinematic.active||state.clearSeq.active||state.victoryComplete)return;adapter.setPlayerPosition?.(state.player.x,state.player.y)}
function publicStart(options={}){completeNotified=false;state.victoryComplete=false;state.clearSeq.active=false;state.cinematic.active=false;state.hasPlayedPhase1Intro=!!options.skipIntro;state.hasPlayedPhase2Intro=false;const patternId=Number(options.patternId);const idx=Number.isFinite(patternId)?PATTERNS.findIndex(p=>p.id===patternId):0;if(idx>=0&&Number.isFinite(patternId)){const group=PATTERNS[idx].g;state.hasPlayedPhase1Intro=true;state.hasPlayedPhase2Intro=group==="team";applyPatternStart(idx,{skipCinematic:true,resetPhaseHp:true})}else startPattern(0,{skipCinematic:!!options.skipIntro,resetPhaseHp:true})}
function publicUpdate(dt){syncExternalPlayerIn();update(Math.max(0,Math.min(.05,dt)));syncExternalPlayerOut();if(state.victoryComplete&&!completeNotified){completeNotified=true;adapter.onComplete?.()}}
function publicHandlePlayerShot(shot){if(!shot||!isPlayerAttackAllowed())return false;const s={x:shot.x,y:shot.y,r:Math.max(2,shot.r||4),damage:Math.max(0,shot.damage||1)*5.5};if(dist(s.x,s.y,state.boss.x,state.boss.y)<state.boss.r+s.r){if(bossShieldedForPattern()){const q=state.q||{};if(q.shieldFlash!==undefined)q.shieldFlash=.22;burst(s.x,s.y,"#8fd7ff",5);return true}damageBoss(s.damage*.28,s.x,s.y);return true}return!!patternShotHit(s)}
function publicPointerDown(x,y){if(state.cinematic.active||state.clearSeq.active||state.victoryComplete||cur().kind!=="math")return false;clickMath(x,y);return true}
function movementBounds(){const maxY=cur().kind==="books"?Math.min(H-25,(state.q?.floor??H)-state.player.r):H-25;return{minX:20,maxX:W-20,minY:90,maxY}}
function publicSkipCurrent(){if(state.victoryComplete)return false;if(state.clearSeq.active){state.clearSeq.stage="clear";state.clearSeq.stageT=2.7;return true}if(state.cinematic.active){state.cinematic.t=CINEMATIC_PRESETS[state.cinematic.type].total;return true}const next=nextPatternInCurrentPhase();applyPatternStart(next,{skipCinematic:true,preserveField:false});return true}
function publicJumpPattern(id){const idx=PATTERNS.findIndex(p=>p.id===Number(id));if(idx<0)return false;const group=PATTERNS[idx].g;state.hasPlayedPhase1Intro=true;state.hasPlayedPhase2Intro=group==="team";applyPatternStart(idx,{skipCinematic:true,resetPhaseHp:true});return true}
function publicPhase1Intro(){state.hasPlayedPhase1Intro=true;playCinematic("phase1Intro",0,{previewOnly:false})}
function publicPhaseTransition(){const firstTeam=PATTERNS.findIndex(p=>p.g==="team");state.hasPlayedPhase1Intro=true;state.hasPlayedPhase2Intro=true;playCinematic("phase1Clear",firstTeam,{chainToAwaken:true,preserveField:false})}
function publicPhase2Intro(){const firstTeam=PATTERNS.findIndex(p=>p.g==="team");state.hasPlayedPhase1Intro=true;state.hasPlayedPhase2Intro=true;playCinematic("phase2Transition",firstTeam,{previewOnly:false})}
function publicClear(){previewBossClearSequence()}
function publicHud(){const pattern=cur();const cinematic=state.cinematic.active?state.cinematic.type:null;const phase=(pattern?.g==="team"||cinematic==="phase2Transition"||state.clearSeq.active)?2:1;const hp=cinematic==="phase1Intro"?2000:cinematic==="phase2Transition"?2200:state.bossHp;return{hp,maxHp:phase===2?2200:2000,phase,patternId:pattern?.id??0,patternTitle:pattern?.title??"",cinematic,clearStage:state.clearSeq?.active?state.clearSeq.stage:null,victoryComplete:!!state.victoryComplete}}
function publicClearEnemyProjectiles(){state.bullets=[];state.stars=[];if(meetingPhasePack)meetingPhasePack.enemyBullets.length=0}
return{canvas,state,patterns:PATTERNS,start:publicStart,update:publicUpdate,render:draw,handlePlayerShot:publicHandlePlayerShot,pointerDown:publicPointerDown,getMovementBounds:movementBounds,getBossHitArea:()=>({x:state.boss.x,y:state.boss.y,r:state.boss.r}),isPlayerAttackAllowed:()=>!state.cinematic.active&&!state.clearSeq.active&&!state.victoryComplete&&!state.patternDone&&cur().kind!=="math",clearEnemyProjectiles:publicClearEnemyProjectiles,applyDamage:(amount)=>damageBoss(Math.max(0,amount||0)),skipCurrent:publicSkipCurrent,jumpToPattern:publicJumpPattern,playPhase1Intro:publicPhase1Intro,playPhaseTransition:publicPhaseTransition,playPhase2Intro:publicPhase2Intro,playClearSequence:publicClear,getHudState:publicHud}
